package com.example.notification_service.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications") public class Notification{@Id private UUID id;@Column(name="event_id",unique=true)private UUID eventId;private String recipient;private String channel;@Column(name="template_code")private String templateCode;private String subject;@Enumerated(EnumType.STRING)private NotificationStatus status;@Column(name="attempt_count")private int attemptCount;@Column(name="last_error")private String lastError;@Column(name="sent_at")private Instant sentAt;@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;@Version private long version;protected Notification(){}public Notification(UUID eventId,String recipient,String template,String subject){id=UUID.randomUUID();this.eventId=eventId;this.recipient=recipient;channel="EMAIL";templateCode=template;this.subject=subject;status=NotificationStatus.PENDING;createdAt=Instant.now();updatedAt=createdAt;}public void sent(){attemptCount++;status=NotificationStatus.SENT;sentAt=Instant.now();updatedAt=sentAt;lastError=null;}public UUID getId(){return id;}public UUID getEventId(){return eventId;}public String getRecipient(){return recipient;}public String getTemplateCode(){return templateCode;}public String getSubject(){return subject;}public NotificationStatus getStatus(){return status;}public int getAttemptCount(){return attemptCount;}public Instant getSentAt(){return sentAt;}}
